#include "evaluator.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct Entry{char*name;Value value;struct Entry*next;}Entry;struct Environment{Entry*head;};static char*dupstr(const char*s){size_t n=strlen(s);char*p=malloc(n+1U);if(p)memcpy(p,s,n+1U);return p;}
Value value_null(void){Value v={VALUE_NULL,{.integer=0}};return v;}Value value_bool(bool b){Value v={VALUE_BOOL,{.boolean=b}};return v;}Value value_int(int64_t i){Value v={VALUE_INT,{.integer=i}};return v;}Value value_float(double f){Value v={VALUE_FLOAT,{.floating=f}};return v;}Value value_string_copy(const char*s){Value v={VALUE_STRING,{.string=dupstr(s)}};if(!v.as.string)v.type=VALUE_NULL;return v;}void value_free(Value*v){if(!v)return;if(v->type==VALUE_STRING)free(v->as.string);v->type=VALUE_NULL;v->as.integer=0;}void print_value(const Value*v){if(!v){printf("null");return;}switch(v->type){case VALUE_NULL:printf("null");break;case VALUE_BOOL:printf("%s",v->as.boolean?"true":"false");break;case VALUE_INT:printf("%lld",(long long)v->as.integer);break;case VALUE_FLOAT:printf("%.17g",v->as.floating);break;case VALUE_STRING:printf("%s",v->as.string?v->as.string:"");break;}}bool value_truthy(const Value*v){if(!v)return false;switch(v->type){case VALUE_NULL:return false;case VALUE_BOOL:return v->as.boolean;case VALUE_INT:return v->as.integer!=0;case VALUE_FLOAT:return v->as.floating!=0.0;case VALUE_STRING:return v->as.string&&v->as.string[0]!='\0';}return false;}
Environment*env_new(void){return calloc(1,sizeof(Environment));}void env_free(Environment*e){if(!e)return;while(e->head){Entry*n=e->head->next;free(e->head->name);value_free(&e->head->value);free(e->head);e->head=n;}free(e);}void env_define(Environment*e,const char*n,Value v){if(!e||!n)return;Entry*x=calloc(1,sizeof(Entry));if(!x)return;x->name=dupstr(n);x->value=v;x->next=e->head;e->head=x;}Value*env_lookup(Environment*e,const char*n){for(Entry*x=e?e->head:NULL;x;x=x->next)if(strcmp(x->name,n)==0)return &x->value;return NULL;}
static Value eval(Environment*e,const AstNode*n){if(!n)return value_null();switch(n->type){case AST_INTEGER:return value_int(n->as.integer);case AST_FLOAT:return value_float(n->as.floating);case AST_BOOLEAN:return value_bool(n->as.boolean);case AST_NULL:return value_null();case AST_STRING:{size_t z=strlen(n->as.string);if(z>=2&&n->as.string[0]=='"'&&n->as.string[z-1]=='"'){char*s=malloc(z-1);if(!s)return value_null();memcpy(s,n->as.string+1,z-2);s[z-2]='\0';Value v=value_string_copy(s);free(s);return v;}return value_string_copy(n->as.string);}case AST_IDENTIFIER:{Value*v=env_lookup(e,n->as.identifier);return v?*v:value_null();}case AST_LET:{Value v=eval(e,n->as.declaration.value);env_define(e,n->as.declaration.name,v);return v;}case AST_RETURN:return eval(e,n->as.return_statement.value);case AST_EXPRESSION_STATEMENT:return eval(e,n->as.expression_statement.expression);case AST_PROGRAM:case AST_BLOCK:{Value last=value_null();for(size_t i=0;i<n->as.block.statements.count;i++){value_free(&last);last=eval(e,n->as.block.statements.items[i]);}return last;}case AST_IF:{Value c=eval(e,n->as.if_statement.condition);bool truth=value_truthy(&c);value_free(&c);return eval(e,truth?n->as.if_statement.then_branch:n->as.if_statement.else_branch);}case AST_UNARY:{Value v=eval(e,n->as.unary.operand);if(n->as.unary.operator_type==TOKEN_BANG){bool b=!value_truthy(&v);value_free(&v);return value_bool(b);}if(n->as.unary.operator_type==TOKEN_MINUS&&v.type==VALUE_INT){v.as.integer=-v.as.integer;return v;}if(n->as.unary.operator_type==TOKEN_MINUS&&v.type==VALUE_FLOAT){v.as.floating=-v.as.floating;return v;}value_free(&v);return value_null();}case AST_BINARY:{Value a=eval(e,n->as.binary.left),b=eval(e,n->as.binary.right);TokenType op=n->as.binary.operator_type;if(op==TOKEN_EQUAL_EQUAL||op==TOKEN_BANG_EQUAL){bool same=a.type==b.type;if(same&&a.type==VALUE_INT)same=a.as.integer==b.as.integer;else if(same&&a.type==VALUE_BOOL)same=a.as.boolean==b.as.boolean;else if(same&&a.type==VALUE_STRING)same=strcmp(a.as.string,b.as.string)==0;else if(same&&a.type==VALUE_NULL)same=true;value_free(&a);value_free(&b);return value_bool(op==TOKEN_EQUAL_EQUAL?same:!same);}if(a.type==VALUE_INT&&b.type==VALUE_INT){int64_t r=0;if(op==TOKEN_PLUS)r=a.as.integer+b.as.integer;else if(op==TOKEN_MINUS)r=a.as.integer-b.as.integer;else if(op==TOKEN_STAR)r=a.as.integer*b.as.integer;else if(op==TOKEN_SLASH&&b.as.integer!=0)r=a.as.integer/b.as.integer;else{value_free(&a);value_free(&b);return value_null();}value_free(&a);value_free(&b);return value_int(r);}if((op==TOKEN_LESS||op==TOKEN_LESS_EQUAL||op==TOKEN_GREATER||op==TOKEN_GREATER_EQUAL)&&a.type==VALUE_INT&&b.type==VALUE_INT){bool r=op==TOKEN_LESS?a.as.integer<b.as.integer:op==TOKEN_LESS_EQUAL?a.as.integer<=b.as.integer:op==TOKEN_GREATER?a.as.integer>b.as.integer:a.as.integer>=b.as.integer;value_free(&a);value_free(&b);return value_bool(r);}if(op==TOKEN_PLUS&&a.type==VALUE_STRING&&b.type==VALUE_STRING){size_t x=strlen(a.as.string),y=strlen(b.as.string);char*s=malloc(x+y+1U);if(!s){value_free(&a);value_free(&b);return value_null();}memcpy(s,a.as.string,x);memcpy(s+x,b.as.string,y+1U);Value v=value_string_copy(s);free(s);value_free(&a);value_free(&b);return v;}value_free(&a);value_free(&b);return value_null();}default:return value_null();}}
Value eval_ast(Environment*e,const AstNode*n){return eval(e,n);}
